import pyomo.environ as pyo

DATA = {
    "budget": 100000.0,          # total money available to invest ($)
    "telecom_min_ratio": 3.0,    # telecom >= 3 * healthcare
    "telecom_cap": 70000.0,      # max invested in telecom ($)
    "return_telecom": 0.03,      # 3% return on telecom
    "return_healthcare": 0.01,   # 1% return on healthcare
    "categories": ["telecom", "healthcare"],
    "returns": {"telecom": 0.03, "healthcare": 0.01},
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Sets
    model.INVESTMENTS = pyo.Set(initialize=d["categories"])

    # Variables (dollars invested per category)
    def invest_bounds(m, i):
        if i == "telecom":
            return (0.0, d["telecom_cap"])
        return (0.0, d["budget"])

    model.invest = pyo.Var(
        model.INVESTMENTS,
        within=pyo.NonNegativeReals,
        bounds=invest_bounds,
    )

    # Objective: maximize total profit
    def obj_rule(m):
        return sum(d["returns"][i] * m.invest[i] for i in m.INVESTMENTS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # Constraint: total invested cannot exceed budget
    def budget_rule(m):
        return sum(m.invest[i] for i in m.INVESTMENTS) <= d["budget"]

    model.budget_limit = pyo.Constraint(rule=budget_rule)

    # Constraint: telecom investment at least 3x healthcare investment
    def ratio_rule(m):
        return m.invest["telecom"] - d["telecom_min_ratio"] * m.invest["healthcare"] >= 0.0

    model.telecom_ratio = pyo.Constraint(rule=ratio_rule)

    # Constraint: telecom investment at most the cap
    def cap_rule(m):
        return m.invest["telecom"] <= d["telecom_cap"]

    model.telecom_cap = pyo.Constraint(rule=cap_rule)

    return model


